// argparse.mjs — minimal replica of Python's argparse for:
//   parser = argparse.ArgumentParser()
//   parser.add_argument('--a', type=str, required=True)
// Behavior verified black-box against the reference executable:
//   - `--a VALUE` and `--a=VALUE`; --a is required.
//   - A separate value starting with '-' is rejected ("expected one argument")
//     unless it is a negative number (-42, -4.2, -.5) or a bare '-'.
//     The `--a=VALUE` form accepts any value, including option-looking ones.
//   - `-h` / `--help` (and unambiguous `--` abbreviations) print help, exit 0.
//   - Unknown options/positionals are collected and reported together as
//     "unrecognized arguments: ..." AFTER the required-argument check.
//   - A `--` token stops option parsing; with no positionals defined, the
//     `--` itself and everything after it become unrecognized arguments.
//   - Exit code 2 for argument errors (usage + error on stderr), 0 for help.
// Constraints: pure ESM, no imports needed, no JSON, no regular expressions.

const LONG_OPTIONS = ['--help', '--a'];

function isDigit(ch) {
  return ch >= '0' && ch <= '9';
}

function isAllDigits(s) {
  if (s.length === 0) return false;
  for (let i = 0; i < s.length; i++) {
    if (!isDigit(s.charAt(i))) return false;
  }
  return true;
}

// Replicates argparse's negative-number matcher ^-\d+$ | ^-\d*\.\d+$
function looksLikeNegativeNumber(s) {
  if (s.length < 2 || s.charAt(0) !== '-') return false;
  const rest = s.slice(1);
  if (isAllDigits(rest)) return true;
  const dot = rest.indexOf('.');
  if (dot === -1) return false;
  if (rest.indexOf('.', dot + 1) !== -1) return false; // at most one dot
  const before = rest.slice(0, dot); // \d* (may be empty)
  const after = rest.slice(dot + 1); // \d+ (must be non-empty)
  if (after.length === 0) return false;
  for (let i = 0; i < before.length; i++) {
    if (!isDigit(before.charAt(i))) return false;
  }
  return isAllDigits(after);
}

// A token is option-like when it starts with '-', is not a bare '-',
// and does not look like a negative number.
function looksLikeOption(s) {
  if (s.length === 0 || s.charAt(0) !== '-') return false;
  if (s === '-') return false;
  return !looksLikeNegativeNumber(s);
}

function basename(path) {
  let end = path.length;
  // Ignore trailing slashes (os.path.basename does not keep them either).
  while (end > 0 && (path.charAt(end - 1) === '/' || path.charAt(end - 1) === '\\')) {
    end--;
  }
  let start = end;
  while (start > 0 && path.charAt(start - 1) !== '/' && path.charAt(start - 1) !== '\\') {
    start--;
  }
  return path.slice(start, end);
}

function usageLine(prog) {
  return 'usage: ' + prog + ' [-h] --a A';
}

function printHelpAndExit(prog) {
  const text =
    usageLine(prog) + '\n' +
    '\n' +
    'options:\n' +
    '  -h, --help  show this help message and exit\n' +
    '  --a A\n';
  process.stdout.write(text);
  process.exit(0);
}

function errorAndExit(prog, message) {
  process.stderr.write(usageLine(prog) + '\n' + prog + ': error: ' + message + '\n');
  process.exit(2);
}

// Resolve a long-option name (without any '=value' part) against the known
// options, honoring argparse's allow_abbrev prefix matching.
// Returns the matched option, or null when unknown; calls fail() on ambiguity.
function resolveLongOption(name, failAmbiguous) {
  for (const opt of LONG_OPTIONS) {
    if (opt === name) return opt; // exact match wins
  }
  const matches = [];
  for (const opt of LONG_OPTIONS) {
    if (opt.startsWith(name)) matches.push(opt);
  }
  if (matches.length === 1) return matches[0];
  if (matches.length > 1) failAmbiguous(matches);
  return null;
}

export function parseArgs(argv) {
  const prog = basename(argv[1] === undefined ? '' : String(argv[1]));
  const args = argv.slice(2);

  let aValue = null;
  let aSeen = false;
  const extras = [];
  let noMoreOptions = false;

  let i = 0;
  while (i < args.length) {
    const tok = args[i];

    if (noMoreOptions) {
      extras.push(tok);
      i++;
      continue;
    }
    if (tok === '--') {
      // No positionals are defined, so the separator itself is also an extra.
      extras.push(tok);
      noMoreOptions = true;
      i++;
      continue;
    }
    if (!looksLikeOption(tok)) {
      extras.push(tok); // positional; none are defined
      i++;
      continue;
    }

    if (tok.startsWith('--')) {
      // Long option, possibly with an inline =value.
      let name = tok;
      let explicit = null;
      const eq = tok.indexOf('=');
      if (eq !== -1) {
        name = tok.slice(0, eq);
        explicit = tok.slice(eq + 1);
      }
      const opt = resolveLongOption(name, (matches) => {
        errorAndExit(
          prog,
          'ambiguous option: ' + name + ' could match ' + matches.join(', ')
        );
      });
      if (opt === '--help') {
        if (explicit !== null) {
          errorAndExit(
            prog,
            "argument -h/--help: ignored explicit argument '" + explicit + "'"
          );
        }
        printHelpAndExit(prog);
      } else if (opt === '--a') {
        if (explicit !== null) {
          aValue = explicit;
          aSeen = true;
          i++;
        } else {
          const next = i + 1 < args.length ? args[i + 1] : null;
          if (next === null || looksLikeOption(next)) {
            errorAndExit(prog, 'argument --a: expected one argument');
          }
          aValue = next;
          aSeen = true;
          i += 2;
        }
      } else {
        extras.push(tok); // unknown long option, kept verbatim (with =value)
        i++;
      }
      continue;
    }

    // Single-dash option. Only -h exists; help fires on the first char and
    // exits, so anything after it in the same token never matters.
    if (tok.charAt(1) === 'h') {
      printHelpAndExit(prog);
    }
    extras.push(tok); // unknown short option, kept verbatim
    i++;
  }

  if (!aSeen) {
    errorAndExit(prog, 'the following arguments are required: --a');
  }
  if (extras.length > 0) {
    errorAndExit(prog, 'unrecognized arguments: ' + extras.join(' '));
  }

  return { a: aValue };
}

